#!/usr/bin/env python3
"""Extract every matter document under documents/ to plain text in extract/.

One deterministic pass replaces per-file ad-hoc extraction. In this workspace
the runtime's scripts/read_doc.py defaults to a podman sandbox that is not
available, so binary documents are parsed with `--in host` (the mode verified
working on every .docx and .xlsx in the base1 rollout). .eml files are
quoted-printable encoded and are decoded with the stdlib email module.

Usage:
    python3 scripts/extract_sources.py [sources_dir] [out_dir]

Defaults: sources_dir=documents, out_dir=extract. Re-running overwrites.
Prints a manifest of source -> extract file -> line count. Continues past a
failing file, lists failures at the end, and exits 1 if any failed, 2 if the
sources directory is missing.
"""

from __future__ import annotations

import subprocess
import sys
from email import policy
from email.message import EmailMessage
from email.parser import BytesParser
from pathlib import Path

BINARY_EXTS = {".docx", ".xlsx", ".pptx", ".pdf"}
READ_DOC = ["python3", "scripts/read_doc.py"]


def extract_binary(path: Path) -> str:
    result = subprocess.run(
        READ_DOC + [str(path), "--in", "host"],
        capture_output=True, text=True, timeout=180,
    )
    if result.returncode != 0:
        raise RuntimeError((result.stderr or "read_doc.py failed").strip())
    return result.stdout


def extract_eml(path: Path) -> str:
    msg = BytesParser(policy=policy.default).parse(path.open("rb"))
    lines = []
    for header in ("From", "To", "Cc", "Date", "Subject"):
        if msg.get(header):
            lines.append(f"{header}: {msg.get(header)}")
    lines.append("")
    body = msg.get_body(preferencelist=("plain", "html"))
    if body is not None:
        lines.append(body.get_content())
    for part in msg.walk():
        if part.get_content_type() == "text/plain" and part is not body:
            try:
                lines.append(part.get_content())
            except Exception:
                pass
    return "\n".join(lines)


def main() -> int:
    src_dir = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("documents")
    out_dir = Path(sys.argv[2]) if len(sys.argv) > 2 else Path("extract")
    if not src_dir.is_dir():
        print(f"sources directory not found: {src_dir}", file=sys.stderr)
        return 2
    out_dir.mkdir(parents=True, exist_ok=True)

    failures: list[tuple[Path, str]] = []
    sources = sorted(p for p in src_dir.iterdir() if p.is_file())
    for path in sources:
        out_path = out_dir / (path.name + ".txt")
        try:
            if path.suffix.lower() in BINARY_EXTS:
                text = extract_binary(path)
            elif path.suffix.lower() == ".eml":
                text = extract_eml(path)
            else:
                text = path.read_text(encoding="utf-8", errors="replace")
            out_path.write_text(text, encoding="utf-8")
            print(f"{path} -> {out_path} ({text.count(chr(10)) + 1} lines)")
        except Exception as e:  # noqa: BLE001
            failures.append((path, f"{type(e).__name__}: {e}"))
            print(f"FAILED: {path}: {type(e).__name__}: {e}", file=sys.stderr)

    print(f"\n{len(sources) - len(failures)}/{len(sources)} extracted to {out_dir}/")
    if failures:
        for path, err in failures:
            print(f"failed: {path}: {err}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
